class Memoizer:
    def __init__(self, maxsize, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.data = {}

    def __call__(self, *args, **kwargs):
        if self.typed:
            key = (type(args[0]), args[1:])
        else:
            key = (args[0], kwargs)

        if key not in self.data:
            self.data[key] = func(*args, **kwargs)
            self.data = dict(sorted(self.data.items(), key=lambda x: x[1], reverse=True))
            while len(self.data) > self.maxsize:
                del self.data[self.data.popitem()]

        return self.data[key]

    def __repr__(self):
        return "Memoizer(maxsize={}, typed={})".format(self.maxsize, self.typed)

return Memoizer
