def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if not hasattr(self, "text"):
        raise ValueError("Object has no property named 'text'.")
    if not isinstance(self.text, str):
        raise ValueError("Object.text property must be a string value.")
    if not hasattr(self, "type"):
        raise ValueError("Object has no property named 'type'.")
    if not isinstance(self.type, str):
        raise ValueError("Object.type property must be a string value.")
    if indent < 0:
        raise ValueError("Indent cannot be negative.")

    s = " " * indent
    s += self.type + ": "
    s += self.text

    if debug:
        if hasattr(self, "id"):
            s += "\n" + " " * (indent + 1) + "id: " + str(self.id)
        if hasattr(self, "metadata"):
            for k, v in self.metadata.items():
                s += "\n" + " " * (indent + 1) + k + ": " + str(v)

