def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    global_args = []
    subparsers = {}
    for unparsed_arg in unparsed_arguments:
        if unparsed_arg.startswith("--"):
            global_args.append(unparsed_arg)
        else:
            subparser_name, subparser_args = unparsed_arg.split(":", maxsplit=1)
            if subparser_name not in subparsers:
                subparsers[subparser_name] = []
            subparsers[subparser_name].append(subparser_args)
    parsers = [argparse.ArgumentParser(prog="parser") for _ in range(len(subparsers))]
    for subparser_name, subparser_args in subparsers.items():
        subparser = subparser_name if subparser_name != "global" else None
        if len(subparser_args) == 0:
            parser_args = []
        else:
            parser_args = ["--name", subparser_args[0]]
        parsers[subparser_name] = argparse.ArgumentParser(prog="parser", add_help=False, parents=[parsers[subparser]])
        parsers[subparser_name].add_argument("--name", help="The name of the parser")
        for i, val in enumerate(subparser_args[1:], start=1):
            parsers[subparser_name].add_argument(f"--arg{i}", help=f"The argument {i}")
    global_namespace, subparser_names = argparse.ArgumentParser().parse_known_args(global_args)
    parsed_arguments = {subparser: parser.parse_args(subparsers[subparser]) for subparser in subparsers}
    parsed_arguments["global"] = global_namespace
    return parsed_arguments

