        return node2
    if isinstance(node1, ruamel.yaml.nodes.ScalarNode):
        return node2
    if isinstance(node1, ruamel.yaml.nodes.MappingNode):
        merged_nodes = {}
        for subnode1, subnode2 in zip(node1.value, node2.value):
            key = subnode1[0].value
            if key in merged_nodes:
                merged_nodes[key] = deep_merge_two_nodes(merged_nodes[key], subnode2)
            else:
                merged_nodes[key] = subnode2
        return ruamel.yaml.nodes.MappingNode(merged_nodes.values())
    print("deep_merge_two_nodes: unsupported tag type", node1.tag)
    return node2
