def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Edge cases to handle:
    # 1. The document does not contain the mandatory fields
    # 2. The document contains XRD in the <Link> tag
    # 3. The document contains JSON in the <Content> tag
    # 4. The JSON contains invalid data (e.g. non-string values for string keys)

    try:
        # If the document contains XRD in the <Link> tag
        if "<Link rel=\"http://axschema.org/foaf/name\"" in document and "<Link rel=\"http://axschema.org/foaf/image\"" in document:
            # Parse the XRD data and extract the required fields
            webfinger = {}
            for tag in ["foaf_name", "foaf_img"]:
                webfinger[tag] = re.findall(r"<Link rel=\"http://axschema.org/foaf/" + tag + "(.*?)<", document)[0]
            return webfinger
        # If the document contains JSON in the <Content> tag
        elif "<Content type=\"application/json\">" in document:
            # Parse the JSON data and extract the required fields
            webfinger = json.loads(document)
            required_fields = ["name", "image"]
            # Verify that the JSON contains the required fields
            for field in required_fields:
                if field not in webfinger:
                    raise Exception("Missing required field '{}'".format(field))
            return webfinger
        # If the document contains invalid data
        else:
            raise Exception("Invalid document")
    except Exception as e:
        # If an exception is raised during parsing, return an empty dictionary
        return {}
